"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2260],{4821:e=>{e.exports=JSON.parse('{"functions":[{"name":"get","desc":"Returns whether a feature flag is enabled.\\n\\nFlags that are missing from the table return `false`, so an undefined flag is\\nalways treated as disabled.","params":[{"name":"flag","desc":"Flag key to read","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"static","source":{"line":115,"path":"src/Shared/Class/FeatureFlags.luau"}},{"name":"set","desc":"Sets the value of a feature flag.\\n\\nRuntime changes only reach readers that call `get()` while rendering \u2014 consumers\\nthat snapshot the flag at require-time or in `init()` keep their old value.","params":[{"name":"flag","desc":"Flag key to write","lua_type":"string"},{"name":"value","desc":"New value for the flag","lua_type":"boolean"}],"returns":[],"function_type":"static","source":{"line":131,"path":"src/Shared/Class/FeatureFlags.luau"}},{"name":"setBulk","desc":"Bulk-applies a table of flag overrides, writing every entry of `newFlags`. Flags\\nthat are absent from `newFlags` keep their current value.","params":[{"name":"newFlags","desc":"Overrides to apply","lua_type":"{ [string]: boolean }"}],"returns":[],"function_type":"static","source":{"line":146,"path":"src/Shared/Class/FeatureFlags.luau"}},{"name":"useModule","desc":"Requires a ModuleScript that returns a `{ [string]: boolean }` table and\\nbulk-applies it through `setBulk()`.\\n\\nThis has no callers in the codebase \u2014 it is an extension hook so a per-project\\nfork can drop in its own overrides module without editing this file.","params":[{"name":"module","desc":"Module returning a table of flag overrides","lua_type":"ModuleScript"}],"returns":[],"function_type":"static","source":{"line":166,"path":"src/Shared/Class/FeatureFlags.luau"}}],"properties":[],"types":[],"name":"FeatureFlags","desc":"Author: dig1t\\n\\nManages feature flags for the game.\\nFeature flags are used to enable or disable certain features in the game.\\nThis is useful for testing new features before they are fully implemented,\\nor for enabling features for a subset of players (A/B testing).\\n\\nFlags live in a single table inside this module. `get()` returns `false` for any\\nflag that is not present in that table, so an unknown, misspelled, or removed\\nflag reads as disabled instead of erroring.\\n\\nMost consumers snapshot flag values once \u2014 either at require-time into a\\nmodule-level local, or inside a controller/service `init()`. `set()` and\\n`setBulk()` do mutate the table at runtime, but those snapshots are never\\nre-read, so a runtime change only reaches code that calls `get()` while\\nrendering (React components). Flipping a flag reliably requires a rebuild.\\n\\nThis module is shared and replicated to both the client and the server, so the\\nvalues in the table below are baked in at build time. There is no runtime sync\\nbetween the two realms \u2014 calling `set()` on one side does not affect the other.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":28,"path":"src/Shared/Class/FeatureFlags.luau"}}')}}]);